    "description": "36氪获悉，天眼查App显示，近日，苏州招兆房地产开发有限公司成立，法定代表人为佘小艺，注册资本7.5亿元，注册地址位于苏州工业园区，经营范围含房地产开发经营、物业管理、住房租赁。股东信息显示，该公司由招商蛇口旗下招商局地产（苏州）有限公司、苏州工业园区建屋发展集团有限公司共同持股，持股比例分别为51%、49%，认缴出资额分别为3.825亿元、3.675亿元。",
    "content": "36氪获悉，天眼查App显示，近日，苏州招兆房地产开发有限公司成立，法定代表人为佘小艺，注册资本7.5亿元，注册地址位于苏州工业园区，经营范围含房地产开发经营、物业管理、住房租赁。股东信息显示，该公司由招商蛇口旗下招商局地产（苏州）有限公司、苏州工业园区建屋发展集团有限公司共同持股，持股比例分别为51%、49%，认缴出资额分别为3.825亿元、3.675亿元。"
