    "content": "中新网太原10月20日电 (记者 杨静)记者20日从山西省教育厅获悉，今年9月1日，新修订的山西省实施《中华人民共和国职业教育法》办法正式施行，标志着山西省职业教育法治保障迈上新台阶。“十五五”时期，山西省将以职业教育法实施办法落地为抓手，重点推进3方面工作，加快构建现代职业教育体系，让高技能人才供给更加精准。"
