    "description": "新华社北京10月20日电（记者周圆、赵怡宁）工业和信息化部信息通信管理局局长谢存20日在国新办举行的新闻发布会上说，前三季度，信息通信行业发展总体平稳。截至9月底，我国智能算力规模达2592EFLOPS（每秒进行百亿亿次浮点运算），同比增长146%，有力支撑我国人工智能产业快速发展。 谢存介绍，增值电信业务扩大对外开放试点稳步实施，截至9月底，外商投资电信企业累计达3455家，较去年同期增长25%；积极开展6G技术试验，促进关键技术优化…",
