    "content": "周二A股市场走势一波三折。 在早盘，主要股指一度冲高，但由于科创资产分化加剧，存储类品种抛压较为沉重，午市后主要股指一度受阻回落。但在尾盘，随着宽基ETF的再度放量，长线资金鱼贯而入，主要股指也随之企稳，上证综指再度收出红盘。看来，短线扬升动能虽欠缺，但稳市资金的护盘意愿较为坚决，下档支撑渐趋强劲。 AI新叙事引发科创资产大分化 近期AI叙事出现新的变化，一方面是AI产业发展方向从硬件端渐渐走向应用端，随之产业链的关注点从上游物料端渐渐转至端侧、物理AI，由此衍生出人形机器人等产业链个股，迅速成为焦点。另一方面则是…"
