    "description": "新华社北京10月20日电 特稿｜创新驱动 开放赋能——海外人士解读中国经济“三季报” 新华社记者钟雅 邓茜 中国国家统计局19日发布数据显示，今年前三季度，中国国内生产总值（GDP）同比增长4.6%，国民经济顶住压力保持平稳运行，呈现动能向新、结构向优的发展态势，发展韧性和活力持续彰显。 国际媒体和观察人士认为，面对复杂多变的外部环境，中国经济展现强大韧性，以创新驱动培育发展新动能，以高水平对外开放共享增长新机遇，以自身稳定发展为世界经…",
    "content": "新华社北京10月20日电 特稿｜创新驱动 开放赋能——海外人士解读中国经济“三季报” 新华社记者钟雅 邓茜 中国国家统计局19日发布数据显示，今年前三季度，中国国内生产总值（GDP）同比增长4.6%，国民经济顶住压力保持平稳运行，呈现动能向新、结构向优的发展态势，发展韧性和活力持续彰显。 国际媒体和观察人士认为，面对复杂多变的外部环境，中国经济展现强大韧性，以创新驱动培育发展新动能，以高水平对外开放共享增长新机遇，以自身稳定发展为世界经济增长持续贡献力量。 逆风突围，增长展现“强韧性” 中东战事、能源冲击、金融风险…"
