    "content": "新华社北京10月20日电（记者魏玉坤）记者20日从国家发展改革委获悉，近日，国家发展改革委会同科技部、工业和信息化部、人力资源社会保障部、应急管理部、国务院国资委等部门推出首批136项标志性重大应用场景项目清单，为新技术新产品规模化应用等提供广阔场景空间。 首批标志性重大应用场景项目对国务院部署的新领域新赛道、产业转型升级、行业领域应用、社会治理服务、民生领域等五大类型应用场景实现全覆盖，涉及新技术1700余项、新产品1200余项、新标准规范2200余项，呈现领域分布新、参与范围广、改革举措多等特点。相关项目将强化…"
