    "description": "中国央行前行长周小川警告，随着大量资金涌入人工智能（AI）及相关基础设施领域，部分投资项目一旦失败，可能引发金融市场动荡甚至危机，呼吁提前研究并储备政策工具，以应对潜在金融风险。 综合澎湃新闻和财联社报道，周小川星期二（10月20日）在上海举行的2026外滩年会“AI与生产率革命：技术跃迁下的宏观冲击”圆桌讨论上指出，随着AI技术发展，“我们无疑会面临部分投资失败、部分投资成功的局面”。 他警告，考虑到流向AI及相关基础设施的资金规模庞…",
    "content": "中国央行前行长周小川警告，随着大量资金涌入人工智能（AI）及相关基础设施领域，部分投资项目一旦失败，可能引发金融市场动荡甚至危机，呼吁提前研究并储备政策工具，以应对潜在金融风险。 综合澎湃新闻和财联社报道，周小川星期二（10月20日）在上海举行的2026外滩年会“AI与生产率革命：技术跃迁下的宏观冲击”圆桌讨论上指出，随着AI技术发展，“我们无疑会面临部分投资失败、部分投资成功的局面”。 他警告，考虑到流向AI及相关基础设施的资金规模庞大，一旦部分投资失败，可能引发金融动荡，甚至酿成危机，届时可能需要采取大规模行动…"
