    "content": "新华社巴黎10月20日电（记者乔本孝）法国总理勒科尔尼20日在社交媒体上发文说，今晚法国各地继续视情况宵禁。 勒科尔尼说，前一晚部分地区宵禁取得良好治安效果。各省政府与市议会沟通后，将“根据当地实际情况”，决定20日夜间至21日凌晨是否在相关城市宵禁。 19日夜间至20日凌晨，巴黎、里昂、波尔多、里尔、尼斯等地局部宵禁。在巴黎，发生严重打砸抢烧事件的共和国广场和莱阿勒购物中心被列入宵禁范围。波尔多和尼斯的宵禁则只适用于未成年人，将持续至本周末。 巴黎市长埃马纽埃尔·格雷瓜尔19日晚说，宵禁应是“例外”，不应成为当前…"
