    "description": "10月20日是世界骨质疏松日。长期以来，骨质疏松症被视为“老年病”，但记者在多家医院采访了解到，因腰背疼痛、骨量偏低前来就诊的年轻患者比例逐年上升，且年轻人对骨骼健康的认知率远低于中老年群体。 35岁白领周女士，为追求“骨感美”长期节食，每天靠咖啡“续命”。一次轻微碰撞后，她发生了腕部骨折，检查后发现骨密度远低于同龄人正常水平。这样的案例在门诊中并不少见。 北京大学第一医院副院长、骨科主任医师孙浩林介绍，骨质疏松症本质是骨量减少，骨的微…",
    "content": "10月20日是世界骨质疏松日。长期以来，骨质疏松症被视为“老年病”，但记者在多家医院采访了解到，因腰背疼痛、骨量偏低前来就诊的年轻患者比例逐年上升，且年轻人对骨骼健康的认知率远低于中老年群体。 35岁白领周女士，为追求“骨感美”长期节食，每天靠咖啡“续命”。一次轻微碰撞后，她发生了腕部骨折，检查后发现骨密度远低于同龄人正常水平。这样的案例在门诊中并不少见。 北京大学第一医院副院长、骨科主任医师孙浩林介绍，骨质疏松症本质是骨量减少，骨的微结构被破坏，骨骼脆性增加，更容易发生骨折的全身性骨病。骨质疏松症早期通常没有明显…"
