    "content": "新华社北京10月20日电 据多家媒体19日报道，保加利亚一家法院已批准对两名德国公民签发欧洲逮捕令，两人涉嫌纵火焚烧美国“星链”卫星互联网系统在保加利亚的地面天线。 检方文件显示，两人9日驾驶德国牌照车辆，从塞尔维亚经保加利亚边境村庄卡洛蒂纳的口岸进入保加利亚，在保加利亚首都索非亚以南一处卫星通信设施纵火，数小时后通过同一口岸返回塞尔维亚。大火导致3座天线完全损毁、2座部分受损，另有3座受到波及。检方已在两人未到案的情况下提出指控。 据保加利亚通讯社报道，如果罪名成立，两人将面临3年至12年刑期。 “星链”是美国太…"
