    "content": "针对多名中国公民近期在出入英国时被英国边境执法人员长时间扣留、盘查，中国驻英国大使馆对此表示严重关切，已向英国提出严正交涉，要求停止任意扣留和盘查中国公民。 中国驻英国大使馆星期一（10月19日）发布通告指出，近期发生多起中国公民出入英国时，遭英国边境执法人员长时间扣留、盘查，以及手机等随身电子设备被查扣的事件。受影响者包括赴英经贸代表团成员、探亲人士及普通游客。 中国驻英国大使馆指出，英方边境执法人员称，相关行动依据英国《2019年反恐怖主义和边境安全法》有关规定展开。使馆强调，中国对此严重关切，已向英国提出严正…"
