    "content": "新华社北京10月20日电 综述｜中国“绿电出海”为发展中国家能源转型添动力 新华社记者 从东南亚光伏电站，到南亚水电项目，再到非洲偏远地区的离网光伏系统，中国绿色能源合作正以多种形式进入发展中国家，既增加当地清洁电力供应，也为就业技术培训和产业发展创造机会。随着能源转型成为越来越多发展中国家面临的重要课题，中国新能源产业链、工程建设和运维能力为相关国家开发利用可再生能源提供了更多选择。 2021年，中国宣布不再新建境外煤电项目。此后，绿色低碳能源成为中国与高质量共建“一带一路”国家开展能源合作的重要方向。中国企业持…"
