    "content": "新华社赫尔辛基10月20日电（记者朱昊晨 徐谦）斯德哥尔摩消息：瑞典隆德大学研究人员参与的一项国际研究发现，火星上一处距今近40亿年的古老岩石地层记录了早期火星反复遭天体撞击的历史。研究表明，频繁的天体撞击不仅形成了陨石坑，还可能是火星早期大范围岩石形成的重要机制。 据隆德大学近日发布的新闻公报，美国国家航空航天局的“毅力”号火星车近期在耶泽罗陨石坑的坑缘外侧探测到一处厚约75米的古老岩石地层。研究团队通过分析火星车传回的照片发现，该处地层由特征和形成方式各异的多个岩层组成。其中，部分岩层主要由质地类似玻璃的球形颗…"
